# install_wattle.py -- ONE-FILE installer for Wattle on a CYD board (ESP32-2432S028 and compatibles).
#
#   In Thonny:  open this file and press the green Run button.
#   Anywhere:   python3 install_wattle.py            (Windows: python install_wattle.py)
#
# This single file carries everything the board needs (the Wattle program files and a small demo) INSIDE it. There is nothing else
# to download, unzip or find. It looks for the board on the USB cable, copies the files onto it, restarts it, and at the end offers to
# put your Wi-Fi name and password on the board (only needed if your programs will use Wi-Fi).
# Needs only Python and the pyserial module on the computer (Thonny already includes both).
#
#   --port /dev/ttyUSB1     use this port (Windows: --port COM5); skips the question when several boards are connected
#   --no-demo               do not copy the demo
#   --yes                   do not ask any question (no Wi-Fi step either)
#   --list                  only list the boards found, and exit
#   --dry-run               only list the files that would be copied, and exit
#   --wifi                  only the Wi-Fi settings (with --status: say whether the board has them; with --remove: delete them)
#   --selftest              check that the files inside this installer are intact, and exit
#
# The board must already run MicroPython (version 1.24 was used for Wattle 0.10). Files with the same names are replaced; other
# files on the board are left alone. Your own files, ID.dat and wifi settings are never touched by the install.
# (The files inside this installer are put there by make_installer.py, a developer tool. Do not edit that part by hand.)
import sys

if sys.implementation.name == "micropython":
    print("This installer must run on your COMPUTER, not on the board.")
    print("In Thonny: choose  Run > Configure interpreter  and select  'Local Python 3'  at the top (the name may differ a little")
    print("in your version of Thonny), click OK, then press Run again. (Thonny cannot use the board and this installer at the same time.)")
    raise SystemExit

import base64
import getpass
import os
import time
import zlib

try:
    import serial
    from serial.tools import list_ports
except ImportError:
    print("The pyserial module is missing. Install it with:   python3 -m pip install pyserial")
    print("(Thonny includes it; if you are using Thonny, check Run > Configure interpreter.)")
    raise SystemExit

HERE = os.path.dirname(os.path.abspath(__file__))
# Runtime and the display driver are copied PRECOMPILED (.mpy). A board cannot compile the 92 KB Runtime.py source itself: it runs out of
# memory ("MemoryError" at start-up, black screen). The .mpy files are made by make_mpy.py (they must match MicroPython 1.24.x).
PROGRAM_FILES = ["Runtime.mpy", "ili9341.mpy", "board_cyd.py", "touch_xpt2046.py", "main.py", "wifi_cipher.py"]
OLD_SOURCES = ["Runtime.py", "ili9341.py"]            # a .py on the board would be used INSTEAD of the .mpy, so these are removed
OPTIONAL_FILES = ["calibrate_touch.py", "fonts/arial_12.fnt", "fonts/arial_16.fnt", "fonts/arial_16b.fnt", "fonts/arial_24.fnt", "fonts/arial_24b.fnt"]   # the last five: the demo's font
FONT = "fonts/dejavusansmono_12.fnt"                  # the font of the on-screen error messages
DEMO = [("hello_demo/hello.json", "hello.json"), ("hello_demo/demo.py", "demo.py"), ("hello_demo/design.txt", "design.txt")]
CHUNK = 768                                           # bytes of a file sent per step
USB_SERIAL_CHIPS = {(0x1A86, 0x7523), (0x1A86, 0x55D4), (0x10C4, 0xEA60), (0x0403, 0x6001), (0x303A, 0x1001)}   # CH340, CH9102, CP210x, FT232, ESP32-C3/S3 built-in USB

