def load(src):
    """The bytes of a file: from inside this installer if it is there, else from the folder next to it, else None."""
    if src in EMBEDDED:
        return zlib.decompress(base64.b64decode(EMBEDDED[src]))
    path = os.path.join(HERE, src)
    if os.path.exists(path):
        with open(path, "rb") as f:
            return f.read()
    return None


def say(text=""):
    print(text, flush=True)


def stop(text):
    say()
    say("STOP: " + text)
    raise SystemExit(1)


def find_ports():
    found = []
    for p in list_ports.comports():
        if (p.vid, p.pid) in USB_SERIAL_CHIPS or "ttyUSB" in p.device or "usbserial" in p.device:
            found.append(p)
    return found


class Board:
    """A tiny raw-REPL client: runs Python snippets on the board and copies files to it."""

    def __init__(self, port):
        try:
            self.s = serial.Serial(port, 115200, timeout=0.2)
        except (serial.SerialException, OSError) as e:
            stop("cannot open %s (%s).\n  Another program is probably using it: close Thonny's connection to the board "
                 "(Run > Configure interpreter > 'Local Python 3'), or any serial monitor, and try again.\n"
                 "  On Linux you may also need:  sudo usermod -aG dialout $USER   (then log out and in)." % (port, e))
        self.port = port
        # Boards with the USB built into the chip (ESP32-C3/S3/C6) are RESET by changes of the DTR/RTS lines: leave the lines alone there
        self.native = "ttyACM" in port or any(p.device == port and p.vid == 0x303A for p in list_ports.comports())

    def read_until(self, marker, timeout):
        buf = b""
        t0 = time.time()
        while time.time() - t0 < timeout:
            d = self.s.read(256)
            if d:
                buf += d
                if buf.endswith(marker) or marker in buf:
                    return buf
        return buf

    def enter_raw(self):
        if not self.native:
            self.s.dtr = False                                # do not let the port opening reset the board mid-way
            self.s.rts = False
        for _ in range(3):
            self.s.write(b"\r\x03\x03")                      # Ctrl-C twice: stop whatever the board is running
            time.sleep(0.2)
            self.s.reset_input_buffer()
            self.s.write(b"\r\x01")                          # Ctrl-A: raw REPL
            if b"raw REPL; CTRL-B to exit" in self.read_until(b">", 2):
                try:                                              # a Wattle browser board that was running has a 30 s watchdog: make it 10 minutes
                    self.run("import machine\ntry:\n machine.WDT(timeout=600000)\nexcept Exception:\n pass")
                except Exception:
                    pass
                return
        stop("the board does not answer on %s. Is MicroPython installed? Try pressing the board's RESET button and run again." % self.port)

    def run(self, code, timeout=15):
        # Raw-REPL reply:  OK <output> \x04 <errors> \x04 >     (everything after "OK" may arrive in the same chunk)
        self.s.write(code.encode() + b"\x04")
        buf = self.read_until(b"OK", 3)
        i = buf.find(b"OK")
        if i < 0:
            stop("the board did not accept a command.")
        rest = buf[i + 2:]
        t0 = time.time()
        while rest.count(b"\x04") < 2 and time.time() - t0 < timeout:
            rest += self.s.read(256)
        parts = rest.split(b"\x04")
        if len(parts) < 3:
            stop("no complete answer from the board (got %r)." % rest[:80])
        result, err = parts[0], parts[1]
        if err.strip():
            raise RuntimeError(err.decode("utf-8", "replace").strip())
        return result.decode("utf-8", "replace")

    def put(self, data, remote):
        """Write the bytes `data` to the file `remote` on the board and check the size."""
        folder = remote.rsplit("/", 1)[0] if "/" in remote else ""
        if folder:
            self.run("import os\ntry:\n os.mkdir(%r)\nexcept OSError:\n pass" % folder)
        self.run("import binascii\nf = open(%r, 'wb')" % remote)
        for i in range(0, len(data), CHUNK):
            self.run("f.write(binascii.a2b_base64(%r))" % base64.b64encode(data[i:i + CHUNK]).decode())
        self.run("f.close()")
        size = int(self.run("import os\nprint(os.stat(%r)[6])" % remote).strip())
        if size != len(data):
            stop("%s arrived with %d bytes instead of %d." % (remote, size, len(data)))

    def remove(self, name):
        self.run("import os\ntry:\n os.remove(%r)\nexcept OSError:\n pass" % name)

    def listdir(self):
        return eval(self.run("import os\nprint(os.listdir())"))

    def read_text(self, name):
        """A text file on the board, or None. (Held in memory only: never printed.)"""
        try:
            return eval(self.run("try:\n print(repr(open(%r).read()))\nexcept OSError:\n print(repr(None))" % name).strip())
        except Exception:
            return None

    def restart(self):
        self.s.write(b"\x02")                                # Ctrl-B: leave the raw REPL
        time.sleep(0.2)
        self.s.rts = True                                    # RTS is wired to the reset pin on these boards
        time.sleep(0.1)
        self.s.rts = False
        self.s.close()


def pick_port(args, what):
    if "--port" in args:
        return args[args.index("--port") + 1]
    ports = find_ports()
    while len(ports) != 1:               # exactly ONE board must be connected: wait until that is so
        if not ports:
            say("No ESP32 board is connected! Please plug in the board you want to set up (use a USB cable that carries data: many cables are charge-only).")
        else:
            say("You have more than one ESP32 board connected! Please remove ALL the other boards before you are able to continue!")
        input("Press Enter when exactly one board is connected (Ctrl+C to give up) ")
        time.sleep(2)
        ports = find_ports()
    say("Board found on %s." % ports[0].device)
    return ports[0].device


def wifi_dialog(b, present, status_only=False, remove=False, ask_first=False):
    """Put the Wi-Fi name and password on the board in the sealed file wifi.dat. Nothing is kept on this computer or printed."""
    id_text = b.read_text("ID.dat") if "ID.dat" in present else None
    id_lines = id_text.split("\n") if id_text else []
    id_has = len(id_lines) > 5 and bool(id_lines[4].strip())
    has_wifi = "wifi.dat" in present
    sealed = False
    if has_wifi:
        head = b.read_text("wifi.dat")
        sealed = bool(head) and head.startswith("wattle1:")
    say("wifi.dat on the board: " + (("yes, sealed" if sealed else "yes, plain text (set it up again to seal it)") if has_wifi else "no"))
    say("Wi-Fi settings in ID.dat (the old place): " + ("yes" if id_has else "no"))
    if status_only:
        return
    if remove:
        b.remove("wifi.dat")
        say("wifi.dat removed.")
        return
    if ask_first:
        say()
        if input("Set up the Wi-Fi name and password on this board now? (Only needed if your programs will use Wi-Fi.) [y/N] ").strip().lower() not in ("y", "yes"):
            say("OK. You can do it later: run this installer again with  --wifi")
            return
    say()
    name = input("Network name (SSID): ").strip()
    if not name:
        say("No network name given; the Wi-Fi settings were not changed.")
        return
    password = getpass.getpass("Password (it is not shown; in Thonny it may be shown, but only on this screen): ")
    if not password:
        say("(No password: the network will be treated as an open network.)")
    text = name + "\n" + password + "\n"
    if "wifi_cipher.py" not in present:
        b.put(load("wifi_cipher.py"), "wifi_cipher.py")
    # The board seals the text itself (its chip id is the key); only the sealed line is stored.
    b.run("import wifi_cipher\nf = open('wifi.dat', 'w')\nf.write(wifi_cipher.seal(%r) + '\\n')\nf.close()" % text)
    check = b.run("import wifi_cipher\nprint(wifi_cipher.unseal(open('wifi.dat').read()) is not None)").strip()
    if check != "True":
        stop("the board could not read back what it sealed. Run this installer again with  --wifi")
    size = int(b.run("import os\nprint(os.stat('wifi.dat')[6])").strip())
    say("wifi.dat written on the board, sealed (%d bytes): it only works on this board. Nothing was saved on this computer." % size)
    if id_has:
        say()
        say("ID.dat on the board still holds Wi-Fi settings in lines 5 and 6.")
        if input("Remove them from ID.dat (wifi.dat now holds them)? [Y/n] ").strip().lower() in ("", "y", "yes"):
            id_lines[4] = ""
            id_lines[5] = ""
            b.run("f = open('ID.dat', 'w')\nf.write(%r)\nf.close()" % "\n".join(id_lines))
            say("Lines 5 and 6 of ID.dat are now empty (the other lines are unchanged).")


def pin_dialog(b, present, status_only=False, remove=False):
    """Browser boards: put a PIN or password on the board in the sealed file pin.dat. Nothing is kept on this computer or printed."""
    has = "pin.dat" in present
    say("pin.dat on the board: " + ("yes: the pages are locked" if has else "no: the pages are open to everyone on your Wi-Fi"))
    if status_only:
        return
    if remove:
        b.remove("pin.dat")
        say("pin.dat removed: the pages are open again.")
        return
    say()
    say("The PIN (or password) is asked once when someone opens the page. Any text will do; it is stored sealed on the board only.")
    pin = getpass.getpass("New PIN or password (not shown): ")
    if not pin:
        say("No PIN given; nothing was changed.")
        return
    if len(pin) < 4:
        stop("that is too short: please use at least 4 characters.")
    if getpass.getpass("Type it again: ") != pin:
        stop("the two did not match; nothing was changed.")
    if "wifi_cipher.py" not in present:
        b.put(load("wifi_cipher.py"), "wifi_cipher.py")
    b.run("import wifi_cipher\nf = open('pin.dat', 'w')\nf.write(wifi_cipher.seal(%r) + '\\n')\nf.close()" % pin)
    check = b.run("import wifi_cipher\nprint(wifi_cipher.unseal(open('pin.dat').read()) == %r)" % pin).strip()
    if check != "True":
        stop("the board could not read back what it sealed. Run  wattle pin  again.")
    say("pin.dat written on the board, sealed: it only works on this board. Nothing was saved on this computer.")
    say("The board restarts now; open the page and it will ask for the PIN.")


# ---- the browser flavour: any ESP32 with Wi-Fi; its screen is a web page that the board serves ----
BROWSER_FILES = [("browser/main.py", "main.py"), ("browser/Runtime.py", "Runtime.py"), ("browser/wnet.py", "wnet.py"),
                 ("browser/webui.html", "webui.html"), ("wifi_cipher.py", "wifi_cipher.py"),
                 ("browser/wsetup.py", "wsetup.py")]
BROWSER_DEMO = [("browser/examples/hello/hello.json", "design.json"), ("browser/examples/hello/hello.py", "demo.py")]
BROWSER_OLD = ["Runtime.mpy", "BRuntime.py", "poc.py"]      # a Runtime.mpy (the CYD's) would be used INSTEAD of the browser's Runtime.py


def _ini_set(section, pairs, ini=None):
    """Set some keys in one [section] of ~/.config/wattle/editor.ini (the Editor's settings file), making the file or the section when it
    is missing. Only those lines change; comments and everything else stay as they are."""
    path = ini or os.path.join(os.path.expanduser("~"), ".config", "wattle", "editor.ini")
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        lines = open(path, encoding="utf-8").read().splitlines() if os.path.exists(path) else []
        for key, value in pairs:
            head = next((i for i, l in enumerate(lines) if l.strip() == "[%s]" % section), None)
            if head is None:
                lines += ([""] if lines else []) + ["[%s]" % section]
                head = len(lines) - 1
            end = next((i for i in range(head + 1, len(lines)) if lines[i].strip().startswith("[")), len(lines))
            hit = next((i for i in range(head + 1, end) if lines[i].split("=", 1)[0].strip() == key and not lines[i].lstrip().startswith(";")), None)
            if hit is not None:
                lines[hit] = "%s = %s" % (key, value)
            else:
                lines.insert(head + 1, "%s = %s" % (key, value))
        open(path, "w", encoding="utf-8").write("\n".join(lines) + "\n")
        return True
    except OSError:
        return False


def remember_board(ip, name, ini=None):
    """Tell the Editor where the browser board is: board_address and board_name. The Editor looks for the board by NAME as well, so it
    still finds it when the router gives the board a new address."""
    return _ini_set("editor", [("board_address", ip), ("board_name", name)], ini)


def remember_cyd(ini=None):
    """Put the CYD board into the Editor's Device menu (the menu lists only devices that exist for this user)."""
    return _ini_set("device.cyd", [("name", 'CYD 2.8" board'), ("width", "320"), ("height", "240"), ("board", "board_cyd")], ini)


def find_address(name="wattle"):
    """Asks the board over the network (never over the cable: reading it with mpremote would stop the program that is starting)."""
    import urllib.request
    for _ in range(14):
        time.sleep(3)
        try:
            log = urllib.request.urlopen("http://%s.local/log" % name, timeout=4).read().decode().split("\n")
            last = max([i for i, l in enumerate(log) if "boot, reset cause" in l] or [0])
            ok = [l for l in log[last:] if "wifi ok" in l]
            return ok[-1].split("wifi ok")[1].strip() if ok else "(see your router's list of devices)"
        except Exception:
            pass
    return None


def install_browser(args):
    yes = "--yes" in args
    demo = "--no-demo" not in args
    name = args[args.index("--name") + 1] if "--name" in args and args.index("--name") + 1 < len(args) else ""
    if name and (not name.replace("-", "").isalnum() or len(name) > 24):
        stop("the name may only have letters, digits and '-' (at most 24): http://%s.local" % name)
    files = BROWSER_FILES + (BROWSER_DEMO if demo else [])
    missing = [src for src, _ in files if load(src) is None]
    if missing:
        stop("these files are missing: " + ", ".join(missing))
    port = pick_port(args, "get Wattle")
    b = Board(port)
    b.enter_raw()
    try:
        present = b.listdir()
    except Exception as e:
        stop("could not read the board's files: %s" % e)
    say("MicroPython answered. Files on the board now: " + (", ".join(sorted(present)) or "(none)"))
    info = b.run("import sys, gc\ngc.collect()\nprint(sys.implementation._machine, '|', '.'.join(str(x) for x in sys.implementation.version[:3]), '|', gc.mem_free())").strip().split(" | ")
    say("Board: %s, MicroPython %s, %s bytes of memory free." % (info[0], info[1], info[2]))
    old = [n for n in BROWSER_OLD if n in present]
    replaced = [dst for _, dst in files if dst in present]
    if old:
        say("These old files will be REMOVED (they would be used instead of the browser files): " + ", ".join(old))
    if replaced:
        say("These will be REPLACED: " + ", ".join(replaced))
    if "main.py" in present and "Runtime.py" not in present:
        say("NOTE: this board already has a main.py of its own; it will be replaced (a copy is kept as main_before_wattle.py).")
    if not yes:
        if input("Install Wattle (browser version) on %s now? [Y/n] " % port).strip().lower() not in ("", "y", "yes"):
            b.s.close()
            stop("cancelled; nothing was changed.")
    if "main.py" in present and "Runtime.py" not in present and "main_before_wattle.py" not in present:
        b.run("import os\nos.rename('main.py', 'main_before_wattle.py')")
    for n in old:
        b.remove(n)
    say()
    say("Copying %d files ..." % len(files))
    for src, dst in files:
        data = load(src)
        say("  %-20s %6d bytes" % (dst, len(data)))
        b.put(data, dst)
    if demo:
        b.put(("design.json\nboard_browser\n").encode(), "design.txt")
    if name:
        b.put((name + "\n").encode(), "name.dat")
        say("  name.dat: the board is called %s" % name)
    if b.run("import os\nprint('pictures' in os.listdir())").strip() != "True":
        b.run("import os\nos.mkdir('pictures')")
    present = b.listdir()
    if not yes:
        say()
        say("The board needs your Wi-Fi to serve the page. (If it has it already, just press Enter at the first question to keep it.)")
        wifi_dialog(b, present)
    elif "wifi.dat" not in present:
        say("No Wi-Fi on this board yet: run  wattle wifi  before you use it.")
    b.s.write(b"import machine\nmachine.reset()\x04")                 # start the new program (not over the cable afterwards!)
    time.sleep(0.5)
    b.s.close()
    say()
    say("Finished. The board is restarting and joining your Wi-Fi (about 15 seconds) ...")
    ip = find_address(name or "wattle")
    say()
    if ip:
        remember_board(ip, name or "wattle")                 # the Editor's Settings window then knows where to look
        say("ALL DONE.  Open this on your phone, tablet or computer (on the same Wi-Fi):")
        say("    http://%s" % ip)
        say("    http://%s.local      (the name: it works on most phones, but not always)" % (name or "wattle"))
        if demo:
            say("You should see \"Wattle is running!\" and a Tap me button that counts.")
    else:
        say("The board did not answer from this computer yet. Wait a little, then open  http://%s.local  on your phone." % (name or "wattle"))
        say("If it still does not work: did you give it your Wi-Fi?   wattle wifi")


def selftest():
    """Check that the files inside this installer decompress, and (when the folder is next to it) match the folder's files."""
    if not EMBEDDED:
        say("Nothing is built into this copy: it reads the files from the folder next to it.")
        return 0
    bad = 0
    for src in sorted(EMBEDDED):
        try:
            data = zlib.decompress(base64.b64decode(EMBEDDED[src]))
        except Exception as e:
            say("  BROKEN   %s (%s)" % (src, e))
            bad += 1
            continue
        path = os.path.join(HERE, src)
        if os.path.exists(path) and open(path, "rb").read() != data:
            say("  DIFFERS  %s (the folder's copy is different: run make_installer.py)" % src)
            bad += 1
        else:
            say("  ok       %-32s %6d bytes" % (src, len(data)))
    say("All %d files inside this installer are intact." % len(EMBEDDED) if not bad else "%d problem(s) found." % bad)
    return 1 if bad else 0


def main(args=None):
    args = sys.argv[1:] if args is None else args
    yes = "--yes" in args
    demo = "--no-demo" not in args

    say("Wattle installer (version 0.10, for the CYD board)")
    say()
    if "--selftest" in args:
        raise SystemExit(selftest())
    if "--list" in args:
        for p in find_ports():
            say("  %s   %s   (USB socket %s)" % (p.device, p.description, p.location or "?"))
        raise SystemExit

    if "--browser" in args:
        install_browser(args)
        return

    files = [(f, f) for f in PROGRAM_FILES] + [(FONT, FONT)] + [(f, f) for f in OPTIONAL_FILES if load(f) is not None]
    if demo:
        files += DEMO
    if load(FONT) is None:                                          # only used by the red error screens: carry on without it
        say("Note: %s is not available; error messages will use the small built-in font." % FONT)
        files = [f for f in files if f[0] != FONT]
    missing = [src for src, _ in files if load(src) is None]
    if missing:
        stop("these files are missing from this installer: " + ", ".join(missing))
    sizes = {dst: len(load(src)) for src, dst in files}

    if "--dry-run" in args:
        say("These files would be copied to the board:")
        for src, dst in files:
            say("  %-32s %6d bytes" % (dst, sizes[dst]))
        raise SystemExit

    port = pick_port(args, "get the change" if ("--wifi" in args or "--pin" in args) else "get Wattle")
    b = Board(port)
    b.enter_raw()
    try:
        present = b.listdir()
    except Exception as e:
        stop("could not read the board's files: %s" % e)
    say("MicroPython answered. Files on the board now: " + (", ".join(sorted(present)) or "(none)"))

    if "--pin" in args:
        pin_dialog(b, present, status_only="--status" in args, remove="--remove" in args)
        b.restart()
        return

    if "--wifi" in args:
        wifi_dialog(b, present, status_only="--status" in args, remove="--remove" in args)
        b.restart()
        return

    old = [n for n in OLD_SOURCES if n in present]
    replaced = [dst for _, dst in files if "/" not in dst and dst in present]
    if old:
        say("These old files will be REMOVED (they would be used instead of the precompiled ones): " + ", ".join(old))
    if replaced:
        say("These will be REPLACED: " + ", ".join(replaced))
    if not yes:
        if input("Install Wattle on %s now? [Y/n] " % port).strip().lower() not in ("", "y", "yes"):
            b.s.close()
            stop("cancelled; nothing was changed.")

    total = sum(sizes.values())
    say()
    for n in old:
        b.remove(n)
    say("Copying %d files (%d KB). This takes about a minute ..." % (len(files), total // 1024))
    for src, dst in files:
        say("  %-32s %6d bytes" % (dst, sizes[dst]))
        b.put(load(src), dst)
    if not yes:
        present = b.listdir()
        wifi_dialog(b, present, ask_first=True)
    b.restart()
    remember_cyd()                                           # the Editor's Device menu then offers this board
    say()
    say("Finished. The board is restarting.")
    if demo:
        say("The screen should show \"Wattle is running!\", a counter \"Taps: 0\" and a button \"Tap me\" within a few seconds. Tap the button: the counter goes up.")
    else:
        say("Wattle is installed. Add a design and a script (see the Quick Guide).")


if __name__ == "__main__":
    main()
